<?php
require_once 'functions.php';require_login();$id=(int)($_GET['id']??0);$u=current_user();$q=$pdo->prepare("SELECT c.*,s.student_number,s.first_name,s.last_name,s.course,s.year_level,s.section,v.violation_name,v.description FROM cases c JOIN students s ON s.student_id=c.student_id JOIN violations v ON v.violation_id=c.violation_id WHERE c.case_id=?");$q->execute([$id]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Notice record not found.');}if($u['role']==='Student'&&(int)$c['student_id']!==(int)$u['student_id']){http_response_code(403);exit('Access denied.');}if($u['role']==='Admin')log_action($pdo,'Generated notice','Notices','Case ID '.$id);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Disciplinary Notice</title><link rel="stylesheet" href="style.css"><style>.notice{max-width:850px;margin:35px auto;background:white;padding:45px;border:1px solid #ccd5e2;border-radius:8px}.notice-head{text-align:center;border-bottom:2px solid #183c6b;padding-bottom:20px;margin-bottom:24px}.notice p{line-height:1.8}@media print{.topbar,.actions,footer{display:none!important}body{background:white}.notice{border:0;margin:0}}</style></head><body><div class="actions" style="max-width:850px;margin:15px auto"><button class="btn primary" onclick="window.print()">Print / Save as PDF</button> <a class="btn" href="records.php">Back</a></div><article class="notice"><header class="notice-head"><h1>STUDENT DISCIPLINARY NOTICE</h1><p>Secure Student Disciplinary Records System</p></header><p><b>Date issued:</b> <?=e(date('F d, Y'))?></p><p><b>Student Number:</b> <?=e($c['student_number'])?><br><b>Student Name:</b> <?=e($c['first_name'].' '.$c['last_name'])?><br><b>Course / Year / Section:</b> <?=e($c['course'].' / '.$c['year_level'].' / '.$c['section'])?></p><p>This notice concerns the disciplinary record described below.</p><p><b>Incident Date:</b> <?=e($c['incident_date'])?><br><b>Violation:</b> <?=e($c['violation_name'])?><br><b>Description:</b> <?=e($c['description'])?><br><b>Sanction:</b> <?=e($c['sanction'])?><br><b>Case Status:</b> <?=e($c['status'])?></p><p><b>Remarks:</b><br><?=nl2br(e($c['remarks']?:'No additional remarks recorded.'))?></p><p>Please contact the Office of Student Affairs for questions or clarification.</p><p style="margin-top:50px">_____________________________<br>Authorized OSA Staff</p><p class="muted tiny">Confidential student information. Handle responsibly.</p></article></body></html>